reports=[]
def add(ticker,name,sector,period,headline,thesis,source,facts,model,rows,extra=None):
    assert len(rows)==14,(ticker,len(rows))
    reports.append(dict(ticker=ticker,name=name,sector=sector,period=period,date='2026-11-13',headline=headline,thesis=thesis,sources=[dict(title=period+' 官方披露',url=source)]+(extra or []),facts=facts,model=model,rows=rows))
